      "question_id": "q1",
      "question": "Do you already have numerical acceptance criteria, such as required accuracy or a detection limit?"
    },
    {
      "question_id": "q2",
      "question": "Over what concentration ranges must protein and fat be monitored in each stream, where relevant?"
    },
    {
      "question_id": "q3",
      "question": "How quickly must a result be available for each stream?"
    },
    {
      "question_id": "q4",
      "question": "Where could a probe be installed for each stream?"
    },
    {
      "question_id": "q5",
      "question": "Would either measurement point be hot, under pressure or prone to build-up?"
    }
  ],
  "plan": {
    "objective": "Assess whether the proposed NIR interfaces can support composition monitoring in each stream against laboratory results for the relevant targets.",
    "samples_and_states": [
      {
        "text": "Collect samples from each stream across client-confirmed composition ranges and relevant physical states.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "reference_measurements": [
      {
        "text": "Pair spectra with laboratory protein and fat results wherever each variable is relevant, matching sampling times.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "setup": [
      {
        "text": "Acquire spectra under matched sample conditions, screening conditional interfaces for usable signals before including them in calibration.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "comparison": [
      {
        "text": "Compare interface-specific chemometric predictions with matched laboratory results across the sampled physical states.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "validation": [
      {
        "text": "Validate each stream’s models on independent material excluded from calibration and model selection.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "go_no_go": [
      {
        "text": "Make a separate go/no-go decision for each stream and relevant target using acceptance criteria agreed with you before testing.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "not_demonstrated": [
      {
        "text": "Achievable prediction errors, response times and performance beyond the tested conditions remain unknown.",
        "claim_type": "UNKNOWN",
        "evidence_ids": []
      }
    ],
    "steps": [
      "Clarify ranges, acceptance criteria, timing and installation constraints.",
      "Collect representative samples and reserve independent validation material.",
      "Obtain time-matched laboratory results for relevant targets.",
      "Set up interfaces and compare spectra and calibrated predictions.",
      "Validate on independent material against agreed criteria.",
      "Decide go or no-go separately for each stream and target."
    ]
  },
  "decision_basis": [
    {
      "text": "Base interface selection on comparison with laboratory results on independent material against client-agreed acceptance criteria.",
      "claim_type": "PROPOSAL",
      "evidence_ids": []
    }
  ]
